        return 1
    total = 0
    for i in range(0, n + 1, 2):
        # Calculate C(n, i) - binomial coefficient
        if i > n - i:
            i = n - i
        coeff = 1
        for k in range(1, i + 1):
            coeff = coeff * (n - i + k) // k
        total += coeff
    return total
